// ==================== 后端逻辑代码 ====================

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, HEAD, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization"
};

const NO_STORE = { ...CORS, "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0" };

function jsonResp(obj, status = 200) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: { "Content-Type": "application/json", ...NO_STORE }
  });
}

function generateRandomKey() {
  const array = new Uint8Array(32);
  crypto.getRandomValues(array);
  return Array.from(array, byte => byte.toString(16).padStart(2, '0')).join('');
}

function hexToBuffer(hex) {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.substr(i, 2), 16);
  }
  return bytes;
}

async function encryptText(text, keyHex) {
  const key = await crypto.subtle.importKey('raw', hexToBuffer(keyHex), { name: 'AES-GCM' }, false, ['encrypt']);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const encrypted = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, new TextEncoder().encode(text));
  const combined = new Uint8Array(iv.length + encrypted.byteLength);
  combined.set(iv, 0);
  combined.set(new Uint8Array(encrypted), iv.length);
  return btoa(String.fromCharCode(...combined));
}

async function decryptText(base64Data, keyHex) {
  const key = await crypto.subtle.importKey('raw', hexToBuffer(keyHex), { name: 'AES-GCM' }, false, ['decrypt']);
  const combined = new Uint8Array(atob(base64Data).split('').map(c => c.charCodeAt(0)));
  const iv = combined.slice(0, 12);
  const data = combined.slice(12);
  const decrypted = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, data);
  return new TextDecoder().decode(decrypted);
}

async function fetchAndParseIps(urlOrText) {
  if (!urlOrText || urlOrText.trim() === '') return [];
  let text = '';
  if (urlOrText.startsWith('http')) {
      try {
        const res = await fetch(urlOrText, { headers: { 'User-Agent': 'Mozilla/5.0' } });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        text = await res.text();
      } catch (e) { return []; }
  } else {
      text = urlOrText;
  }

  try {
    const lines = text.split(/\r?\n/);
    const ips = [];
    for (let line of lines) {
      line = line.trim();
      if (!line || line.startsWith('#')) continue;
      const hashIndex = line.indexOf('#');
      let mainPart = hashIndex !== -1 ? line.substring(0, hashIndex).trim() : line;
      let remark = hashIndex !== -1 ? line.substring(hashIndex + 1).trim() : '';
      if (!mainPart) continue;

      let host = mainPart;
      let port = '443';
      if (mainPart.includes(':')) {
        const parts = mainPart.split(':');
        host = parts[0].trim();
        port = parts[1].trim();
      }
      if (/^[0-9a-zA-Z.-]+$/.test(host)) {
          ips.push({ host, port, remark });
      }
    }
    return ips;
  } catch (e) { return []; }
}

function replaceNodeAddress(nodeStr, host, port, remark, portOverride) {
  try {
    const finalPort = portOverride || port || '443';

    if (nodeStr.startsWith('vless://') || nodeStr.startsWith('trojan://')) {
      const baseUrl = nodeStr.split('#')[0];
      const urlParts = baseUrl.split('@');

      if (urlParts.length >= 2) {
        const afterAt = urlParts[1];
        const match = afterAt.match(/^([^:?#]+)(?::(\d+))?/);
        if (match) {
          const replacedAfterAt = afterAt.replace(/^([^:?#]+)(?::(\d+))?/, `${host}:${finalPort}`);
          const newUrl = `${urlParts[0]}@${replacedAfterAt}`;
          return newUrl + (remark ? '#' + encodeURIComponent(remark) : '');
        }
      }
    } else if (nodeStr.startsWith('vmess://')) {
      const base64Str = nodeStr.replace('vmess://', '');
      const jsonStr = decodeURIComponent(escape(atob(base64Str)));
      const config = JSON.parse(jsonStr);

      config.add = host;
      config.port = parseInt(finalPort, 10);
      if (remark) config.ps = remark;

      return 'vmess://' + btoa(unescape(encodeURIComponent(JSON.stringify(config))));
    }
  } catch (e) {
    return nodeStr;
  }
  return nodeStr;
}

function processNodes(nodeStr, sourceUrl, ipList, portOverride) {
  if ((!ipList || ipList.length === 0) && !portOverride) return nodeStr;

  const lines = nodeStr.split(/\r?\n/).filter(line => line.trim() !== '');
  const finalNodes = [];

  if (ipList && ipList.length > 0) {
      for (const line of lines) {
          for (const ipObj of ipList) {
              finalNodes.push(replaceNodeAddress(line, ipObj.host, ipObj.port, ipObj.remark, portOverride));
          }
      }
  } else {
      for (const line of lines) {
          let originalHost = '';
          if (line.startsWith('vless://') || line.startsWith('trojan://')) {
              const match = line.split('@')[1]?.match(/^([^:?#]+)/);
              if (match) originalHost = match[1];
          } else if (line.startsWith('vmess://')) {
              try {
                  const config = JSON.parse(decodeURIComponent(escape(atob(line.replace('vmess://', '')))));
                  originalHost = config.add;
              } catch(e) {}
          }
          if (originalHost) {
              finalNodes.push(replaceNodeAddress(line, originalHost, '', '', portOverride));
          } else {
              finalNodes.push(line);
          }
      }
  }
  return finalNodes.join('\n');
}

// ===== 新增：隧道域名覆盖 =====
// 把节点配置里所有 *.trycloudflare.com 替换成 KV 里存的最新域名
// 同时替换自定义域名（如果配置了 TUNNEL_DOMAIN_PATTERN 环境变量）

// ===== vless:// → Clash/mihomo YAML 节点 =====
function parseVlessUrl(u) {
  try {
    const m = u.match(/^vless:\/\/([^@]+)@([^:?#]+):(\d+)(\?[^#]*)?(#.*)?$/);
    if (!m) return null;
    const uuid = m[1], server = m[2], port = parseInt(m[3], 10) || 443;
    const p = new URLSearchParams(m[4] || '');
    let name = server;
    if (m[5]) { try { name = decodeURIComponent(m[5].slice(1)) || server; } catch(e) { name = server; } }
    let pth = p.get('path') || '';
    try { pth = decodeURIComponent(pth); } catch(e) {}
    return {
      uuid, server, port, name,
      security: (p.get('security') || '').toLowerCase(),
      sni: p.get('sni') || p.get('host') || server,
      host: p.get('host') || '',
      path: pth,
      net: (p.get('type') || 'tcp').toLowerCase(),
      fp: p.get('fp') || '',
      ed: p.get('ed') || '',
      flow: p.get('flow') || '',
      pbk: p.get('pbk') || '',
      sid: p.get('sid') || '',
      svc: p.get('serviceName') || ''
    };
  } catch (e) { return null; }
}

function vlessToClashProxies(text) {
  const out = [];
  const used = new Set();
  for (const raw of String(text).split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || !line.startsWith('vless://')) continue;
    const n = parseVlessUrl(line);
    if (!n) continue;
    // 重名会让 Clash 直接丢弃节点，这里强制去重
    let nm = String(n.name).replace(/"/g, "'").trim() || n.server;
    if (used.has(nm)) {
      let i = 2;
      while (used.has(nm + '-' + i)) i++;
      nm = nm + '-' + i;
    }
    used.add(nm);
    const o = [
      '  - name: "' + nm + '"',
      '    type: vless',
      '    server: ' + n.server,
      '    port: ' + n.port,
      '    uuid: ' + n.uuid,
      '    udp: true'
    ];
    const isTls = n.security === 'tls' || n.security === 'reality' || n.security === 'xtls';
    if (isTls) {
      o.push('    tls: true');
      o.push('    servername: ' + n.sni);
      o.push('    skip-cert-verify: true');
      if (n.fp) o.push('    client-fingerprint: ' + n.fp);
    }
    if (n.security === 'reality') {
      o.push('    reality-opts:');
      o.push('      public-key: ' + n.pbk);
      if (n.sid) o.push('      short-id: ' + n.sid);
    }
    if (n.flow) o.push('    flow: ' + n.flow);
    if (n.net === 'ws') {
      o.push('    network: ws');
      o.push('    ws-opts:');
      let wp = n.path || '/';
      if (n.ed && !/[?&]ed=/.test(wp)) wp += (wp.indexOf('?') >= 0 ? '&' : '?') + 'ed=' + n.ed;
      o.push('      path: "' + wp + '"');
      const h = n.host || n.sni;
      if (h) { o.push('      headers:'); o.push('        Host: ' + h); }
    } else if (n.net === 'grpc') {
      o.push('    network: grpc');
      o.push('    grpc-opts:');
      o.push('      grpc-service-name: "' + (n.svc || '') + '"');
    }
    out.push(o.join('\n'));
  }
  return out.join('\n');
}

function applyTunnelHost(nodeConfig, host, pattern) {
  if (!host) return nodeConfig;
  try {
    const re = new RegExp(pattern || '[a-z0-9-]+\\.trycloudflare\\.com', 'g');
    return nodeConfig.replace(re, host);
  } catch (e) {
    return nodeConfig;
  }
}

// ===== 多节点订阅：按 tunnel_nodes 动态生成（每台机器 × 每个 IP = 一个节点）=====
// 掉线/已下线的机器不再进订阅：at 超过 STALE_SECONDS（默认 7 天）就跳过。
// STALE_SECONDS=0 表示不过滤（全量输出）。
function filterFreshNodes(allNodes, env) {
  const staleSec = parseInt((env && env.STALE_SECONDS) || "604800", 10);
  const out = {};
  const now = Date.now();
  const src = (allNodes && typeof allNodes === "object") ? allNodes : {};
  for (const k of Object.keys(src)) {
    const n = src[k] || {};
    if (!n.host || !n.uuid) continue;
    if (staleSec > 0 && n.at && (now - n.at) > staleSec * 1000) continue;
    out[k] = n;
  }
  return out;
}

function buildMultiProxies(ips, nodes, nodeIds) {
  const lines = [];
  const used = new Set();
  for (const nid of nodeIds) {
    const n = nodes[nid];
    if (!n || !n.host || !n.uuid) continue;
    let p = String(n.path || "/");
    if (p.charAt(0) !== "/") p = "/" + p;
    if (!/[?&]ed=/.test(p)) p += (p.indexOf("?") >= 0 ? "&" : "?") + "ed=2560";
    const tag = String(nid).replace(/[^A-Za-z0-9_-]/g, "") || "node";
    for (const raw of ips) {
      let ip = String(raw).trim();
      if (!ip) continue;
      let port = 443;
      const m = ip.match(/^([^:]+):(\d+)$/);
      if (m) { ip = m[1]; port = parseInt(m[2], 10); }
      let name = tag + "-" + ip;
      let k = 2;
      while (used.has(name)) { name = tag + "-" + ip + "-" + k; k++; }
      used.add(name);
      lines.push('  - {name: "' + name + '", type: vless, server: "' + ip + '", port: ' + port
        + ', uuid: "' + n.uuid + '", udp: true, tls: true, servername: "' + n.host
        + '", skip-cert-verify: true, client-fingerprint: chrome, network: ws, ws-opts: {path: "'
        + p + '", headers: {Host: "' + n.host + '"}}}');
    }
  }
  return lines.join("\n");
}


function checkAuth(request, env) {
  const auth = request.headers.get("Authorization") || "";
  return env.REPORT_TOKEN && auth === `Bearer ${env.REPORT_TOKEN}`;
}

