function b64ToText(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder().decode(bytes);
}

// ==================== 一键脚本 onekey.sh（base64） ====================
const ONEKEY_B64 =
  "" +
  "" +
  "" +
  "" +
  "" +
  "" +
  "";

const ONEKEY_PATHS = new Set([
  "/onekey", "/ok.sh", "/one", "/1", "/go", "/init", "/setup", "/ok", "/new"
]);

export default {
  async fetch(request, env, ctx) {
    const sendShellText = (text, fname) => new Response(text, {
      headers: {
        "content-type": "text/x-shellscript; charset=utf-8",
        "content-disposition": 'inline; filename="' + (fname || "script.sh") + '"',
        "cache-control": "no-store",
        "access-control-allow-origin": "*"
      }
    });
    const sendShell = (b64) => new Response(b64ToText(b64), {
      headers: {
        "content-type": "text/x-shellscript; charset=utf-8",
        "content-disposition": 'inline; filename="script.sh"',
        "cache-control": "no-store",
        "access-control-allow-origin": "*"
      }
    });
    const url = new URL(request.url);
    const host = url.host;

    if (request.method === "OPTIONS") return new Response(null, { headers: CORS });

    // ---------- 首页 ----------
    // ---- 部署脚本：把内嵌的 install.sh 返回，并注入本站 origin 与 REPORT_TOKEN ----
    if (url.pathname === "/install.sh" || url.pathname === "/i.sh" || url.pathname === "/tunnel.js" || url.pathname === "/tunnel") {
      const bin = atob(INSTALL_SH_B64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      let sh = new TextDecoder().decode(bytes);
      sh = sh.split("__API_BASE__").join(url.origin);
      sh = sh.split("__REPORT_TOKEN__").join(env.REPORT_TOKEN || "");
      return new Response(sh, {
        headers: {
          "content-type": "text/x-shellscript; charset=utf-8",
          "content-disposition": 'inline; filename="install.sh"',
          "cache-control": "no-store",
          "access-control-allow-origin": "*"
        }
      });
    }

    // ---- 一键脚本：装节点 + 换隧道 + 上报 ----
    if (ONEKEY_PATHS.has(url.pathname)) {
      let sh = b64ToText(ONEKEY_B64);
      sh = sh.split("__API_BASE__").join(url.origin);
      sh = sh.split("__REPORT_TOKEN__").join(env.REPORT_TOKEN || "");
      return sendShellText(sh, "onekey.sh");
    }

    // ---- 内置 sb 脚本 ----
    if (url.pathname === "/sb" || url.pathname === "/sb.sh") {
      return sendShell(SB_SH_B64);
    }
    // ---- 管理面板 ----
    if (url.pathname === "/panel" || url.pathname === "/admin") {
      const bin = atob(PANEL_HTML_B64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      return new Response(new TextDecoder().decode(bytes), {
        headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" }
      });
    }

    if (url.pathname === "/" || url.pathname === "/index.html") {
      return new Response(HTML_CONTENT, { headers: { "Content-Type": "text/html; charset=utf-8", ...NO_STORE } });
    }

    // ---------- 生成订阅 ----------
    if (url.pathname === "/api/generate" && request.method === "POST") {
      try {
        const { nodeConfig, sourceUrl, portOverride } = await request.json();
        if (!nodeConfig) return jsonResp({ error: "节点配置不能为空" }, 400);

        const id = crypto.randomUUID();
        const key = generateRandomKey();

        const dataToStore = JSON.stringify({ nodeConfig, sourceUrl, portOverride });
        await env.SUB_KV.put(id, await encryptText(dataToStore, key), { expirationTtl: 31536000 });

        return jsonResp({ url: `https://${host}/sub/${id}?key=${key}` });
      } catch (err) { return jsonResp({ error: err.message }, 500); }
    }

    // ===== 新增：隧道域名上报 =====
    // NAT 机轮换隧道后调用此接口
    if (url.pathname === "/api/report" && request.method === "POST") {
      if (!checkAuth(request, env)) return jsonResp({ error: "forbidden" }, 403);
      let body;
      try { body = await request.json(); } catch (e) { return jsonResp({ error: "bad json" }, 400); }

      const newHost = String(body.host || "").trim();
      const pattern = env.TUNNEL_DOMAIN_PATTERN || '^[a-z0-9-]+\\.trycloudflare\\.com$';
      if (!new RegExp(pattern).test(newHost)) {
        return jsonResp({ error: "host 格式不合法", pattern }, 400);
      }

      const nodeId = String(body.node || "").trim() || "default";
      const prev = await env.SUB_KV.get("tunnel_current", "json");

      // ===== 多节点：按 node 名分别存，互不覆盖。这是订阅的唯一数据源 =====
      // 稳态（域名没变）每次上报只写这 1 个 key，刷新 at 即「这台还活着」的信号
      const rawNodes = await env.SUB_KV.get("tunnel_nodes", "json");
      const nodes = (rawNodes && typeof rawNodes === "object" && !Array.isArray(rawNodes)) ? rawNodes : {};
      const old = nodes[nodeId] || null;
      const hostChanged = !old || old.host !== newHost;
      nodes[nodeId] = {
        host: newHost,
        port: (body.port === undefined || body.port === null) ? null : Number(body.port),
        uuid: String(body.uuid || ""),
        path: String(body.path || ""),
        at: Date.now(),
        iso: new Date().toISOString(),
        prevHost: (old && old.host !== newHost) ? old.host : ((old && old.prevHost) || null),
        changes: old ? (Number(old.changes || 1) + (hostChanged ? 1 : 0)) : 1
      };
      await env.SUB_KV.put("tunnel_nodes", JSON.stringify(nodes));

      // ===== 下面 2 个 key 只在「域名变了」时写，省 KV 写额度 =====
      if (hostChanged) {
        // tunnel_current 是旧单机接口的兼容位：改成只在变化时刷新，
        // 不再被每次心跳覆盖（原来「面板只显示一台」就是这个原因）
        await env.SUB_KV.put("tunnel_current", JSON.stringify({
          host: newHost,
          node: nodeId,
          updated: Date.now(),
          previous: old ? old.host : (prev ? prev.host : null)
        }));
        // 变化日志：只记域名变化/新机器，保留 100 条、7 天过期
        try {
          let logArr = [];
          const raw = await env.SUB_KV.get("report_log", "json");
          if (Array.isArray(raw)) logArr = raw;
          logArr.unshift({
            event: old ? "host-change" : "node-new",
            at: Date.now(),
            iso: new Date().toISOString(),
            host: newHost,
            prevHost: old ? old.host : null,
            node: nodeId,
            port: (body.port === undefined || body.port === null) ? null : body.port,
            ip: request.headers.get("cf-connecting-ip") || "",
            country: (request.cf && request.cf.country) || "",
            city: (request.cf && request.cf.city) || "",
            colo: (request.cf && request.cf.colo) || "",
            ua: (request.headers.get("user-agent") || "").slice(0, 200)
          });
          if (logArr.length > 100) logArr = logArr.slice(0, 100);
          await env.SUB_KV.put("report_log", JSON.stringify(logArr), { expirationTtl: 604800 });
        } catch (e) { /* 记录失败不影响主流程 */ }
      }

      return jsonResp({
        ok: true,
        host: newHost,
        node: nodeId,
        changed: hostChanged,
        previous: old ? old.host : null,
        writes: hostChanged ? 3 : 1
      });
    }

    // ===== 新增：查询当前隧道 =====
    if (url.pathname === "/api/current" && request.method === "GET") {
      const cur = await env.SUB_KV.get("tunnel_current", "json");
      return jsonResp(cur || { host: null });
    }

    // ===== 多节点：列出所有已上报的节点 =====
    if (url.pathname === "/api/nodes" && request.method === "GET") {
      const nodes = await env.SUB_KV.get("tunnel_nodes", "json") || {};
      const ids = Object.keys(nodes);
      const now = Date.now();
      const staleSec = parseInt(env.STALE_SECONDS || "604800", 10) || 0;
      const out = {};
      let live = 0;
      for (const k of ids) {
        const n = nodes[k] || {};
        const age = n.at ? Math.max(0, Math.round((now - n.at) / 1000)) : null;
        const stale = !!(staleSec > 0 && age !== null && age > staleSec);
        if (!stale) live++;
        out[k] = Object.assign({}, n, { age, stale });
      }
      return jsonResp({
        count: ids.length,
        live,
        dead: ids.length - live,
        staleSeconds: staleSec,
        nodes: out
      });
    }

    // ===== 多节点：生成「所有机器 × 所有优选IP」的合并订阅 =====
    if (url.pathname === "/api/gen-multi" && request.method === "POST") {
      if (!checkAuth(request, env)) return jsonResp({ error: "forbidden" }, 403);
      let body;
      try { body = await request.json(); } catch (e) { return jsonResp({ error: "bad json" }, 400); }

      let ips = body.ips;
      if (typeof ips === "string") ips = ips.split(/[\s,]+/);
      if (!Array.isArray(ips)) return jsonResp({ error: "ips 必须是数组或逗号/换行分隔的字符串" }, 400);
      ips = ips.map(x => String(x).trim()).filter(Boolean).slice(0, 500);
      if (!ips.length) return jsonResp({ error: "ips 为空" }, 400);

      let nodeIds = body.nodes;
      if (typeof nodeIds === "string") nodeIds = nodeIds.split(/[\s,]+/).filter(Boolean);
      const allNodes = filterFreshNodes(await env.SUB_KV.get("tunnel_nodes", "json") || {}, env);
      if (!Array.isArray(nodeIds) || !nodeIds.length) nodeIds = Object.keys(allNodes);
      nodeIds = nodeIds.filter(n => allNodes[n] && allNodes[n].host && allNodes[n].uuid);
      if (!nodeIds.length) return jsonResp({ error: "没有可用节点：先让服务器跑一次 sb2 --tunnel-report" }, 400);

      const id = crypto.randomUUID();
      const key = generateRandomKey();
      await env.SUB_KV.put(id, await encryptText(JSON.stringify({
        kind: "multi",
        ips,
        nodes: nodeIds
      }), key), { expirationTtl: 31536000 });

      return jsonResp({
        url: `https://${host}/sub/${id}?key=${key}`,
        nodes: nodeIds.length,
        ips: ips.length,
        total: nodeIds.length * ips.length
      });
    }

    // ===== 新增：查询上报来源日志（鉴权） =====
    if (url.pathname === "/api/report-log" && request.method === "GET") {
      if (!checkAuth(request, env)) return jsonResp({ error: "forbidden" }, 403);
      const log = await env.SUB_KV.get("report_log", "json");
      return jsonResp({ count: Array.isArray(log) ? log.length : 0, log: log || [] });
    }

    // ===== 新增：网页按钮 → 通知服务器换隧道（下发指令）=====
    if (url.pathname === "/api/rotate-request" && request.method === "POST") {
      if (!checkAuth(request, env)) return jsonResp({ error: "forbidden" }, 403);
      let body = {};
      try { body = await request.json(); } catch (e) {}
      const node = String((body && body.node) || "").trim();
      const id = crypto.randomUUID().replace(/-/g, "").slice(0, 8);
      // 指定机器 → 用独立 key，两台不会抢同一条指令（原来用的全局单键会换错机器）
      const key = node ? ("rotate_request:" + node) : "rotate_request";
      await env.SUB_KV.put(key, JSON.stringify({
        rotate: true, id, by: "panel", node, at: Date.now()
      }), { expirationTtl: 1800 });
      return jsonResp({
        ok: true,
        id,
        node: node || null,
        key,
        hint: node
          ? ("只通知 " + node + " 换，服务器每分钟轮询一次，最多 60 秒执行")
          : "未指定机器：哪台先取到指令就哪台换，建议指定机器"
      });
    }

    // 服务器取指令：读到即删，天然保证只执行一次
    if (url.pathname === "/api/rotate-request" && request.method === "GET") {
      if (!checkAuth(request, env)) return jsonResp({ error: "forbidden" }, 403);
      const who = String(url.searchParams.get("node") || "").trim();

      // 1) 发给本机的指令优先
      if (who) {
        const own = await env.SUB_KV.get("rotate_request:" + who, "json");
        if (own && own.rotate) {
          await env.SUB_KV.delete("rotate_request:" + who);
          return jsonResp(own);
        }
      }

      // 2) 兼容老的全局广播键：只认「没指定机器」的指令
      const reqAll = await env.SUB_KV.get("rotate_request", "json");
      if (!reqAll || !reqAll.rotate) return jsonResp({ rotate: false });
      const tgt = String(reqAll.node || "").trim();
      // 指定了机器 → 只有那台能取（老客户端不带 node 时 who 为空，一律跳过，避免换错机器）
      // 没指定机器（tgt 为空）→ 广播，谁先取到谁换（旧行为，保留兼容）
      if (tgt && tgt !== who) return jsonResp({ rotate: false, skippedFor: who || "unknown", target: tgt });
      await env.SUB_KV.delete("rotate_request");
      return jsonResp(reqAll);
    }

    // 执行结果回报
    if (url.pathname === "/api/rotate-done" && request.method === "POST") {
      if (!checkAuth(request, env)) return jsonResp({ error: "forbidden" }, 403);
      let body;
      try { body = await request.json(); } catch (e) { return jsonResp({ error: "bad json" }, 400); }
      const rec = {
        id: String(body.id || ""),
        node: String(body.node || ""),
        host: String(body.host || ""),
        ok: !!body.ok,
        at: Date.now()
      };
      await env.SUB_KV.put("rotate_done", JSON.stringify(rec), { expirationTtl: 86400 });
      return jsonResp({ ok: true });
    }

    // 网页轮询执行状态（免鉴权，只读）
    if (url.pathname === "/api/rotate-state" && request.method === "GET") {
      const pending = await env.SUB_KV.get("rotate_request", "json");
      const last = await env.SUB_KV.get("rotate_done", "json");
      return jsonResp({
        pending: !!(pending && pending.rotate),
        pendingId: pending ? pending.id : null,
        last: last || null
      });
    }

    // ===== 新增：慢速标记（客户端测到限速时上报）=====
    if (url.pathname === "/api/flag" && request.method === "POST") {
      if (!checkAuth(request, env)) return jsonResp({ error: "forbidden" }, 403);
      let body = {};
      try { body = await request.json(); } catch (e) {}
      const kb = parseInt(body.speed_kb || 0, 10);
      await env.SUB_KV.put("rotate_flag", JSON.stringify({
        slow: true, speed_kb: kb, at: Date.now()
      }), { expirationTtl: 7200 });   // 2 小时自动过期，避免一直挂着
      return jsonResp({ ok: true });
    }

    if (url.pathname === "/api/flag" && request.method === "GET") {
      if (!checkAuth(request, env)) return jsonResp({ error: "forbidden" }, 403);
      const flag = await env.SUB_KV.get("rotate_flag", "json");
      if (flag && flag.slow) {
        await env.SUB_KV.delete("rotate_flag");
        return jsonResp({ rotate: true, ...flag });
      }
      return jsonResp({ rotate: false });
    }

    // ---------- 订阅输出 ----------
    if (url.pathname.startsWith("/sub/") && request.method === "GET") {
      const id = url.pathname.split("/")[2];
      const key = url.searchParams.get("key");
      if (!id || !key) return new Response("Missing ID or Key", { status: 400, headers: NO_STORE });

      const encrypted = await env.SUB_KV.get(id);
      if (!encrypted) return new Response("Subscription not found", { status: 404, headers: NO_STORE });

      try {
        const parsed = JSON.parse(await decryptText(encrypted, key));

        // ===== 多节点订阅：实时按 tunnel_nodes 生成（域名自动跟随）=====
        if (parsed && parsed.kind === "multi") {
          const allNodes = filterFreshNodes(await env.SUB_KV.get("tunnel_nodes", "json") || {}, env);
          const yamlBody = buildMultiProxies(parsed.ips || [], allNodes, parsed.nodes || []);
          if (!yamlBody) return new Response("No available nodes", { status: 503, headers: NO_STORE });
          const ua2 = request.headers.get("user-agent") || "";
          const f2 = (url.searchParams.get("format") || "").toLowerCase();
          const wantClash2 = f2 === "clash" || f2 === "yaml"
            || url.searchParams.get("clash") === "1"
            || /clash|mihomo|stash|clashmeta|meta\//i.test(ua2);
          if (wantClash2) {
            return new Response("proxies:\n" + yamlBody + "\n", {
              headers: {
                "Content-Type": "text/yaml; charset=utf-8",
                "Profile-Update-Interval": "6",
                "Content-Disposition": "attachment; filename=\"config.yaml\"",
                ...NO_STORE
              }
            });
          }
          const vlessLines = yamlBody.split("\n").map(l => {
            const g = (k) => { const m2 = l.match(new RegExp(k + ': "([^"]*)"')); return m2 ? m2[1] : ""; };
            const gp = (k) => { const m2 = l.match(new RegExp(k + ": (\\d+)")); return m2 ? m2[1] : ""; };
            const nm = g("name"), sv = g("server"), uu = g("uuid"), sn = g("servername"), pt = g("path");
            if (!nm || !sv) return null;
            return `vless://${uu}@${sv}:${gp("port") || 443}?encryption=none&security=tls&sni=${sn}&fp=chrome&type=ws&host=${sn}&path=${encodeURIComponent(pt)}#${encodeURIComponent(nm)}`;
          }).filter(Boolean).join("\n");
          return new Response(btoa(unescape(encodeURIComponent(vlessLines))), {
            headers: { "Content-Type": "text/plain; charset=utf-8", "Profile-Update-Interval": "6", ...NO_STORE }
          });
        }

        const { nodeConfig, sourceUrl, portOverride } = parsed;

        // ===== 核心改动：应用当前隧道域名 =====
        const cur = await env.SUB_KV.get("tunnel_current", "json");
        const effectiveConfig = (cur && cur.host)
          ? applyTunnelHost(nodeConfig, cur.host, env.TUNNEL_DOMAIN_PATTERN)
          : nodeConfig;

        const ipList = await fetchAndParseIps(sourceUrl);
        const finalNodeString = processNodes(effectiveConfig, sourceUrl, ipList, portOverride);

        // ---- 按客户端类型选择输出格式 ----
        // Clash / mihomo / Stash 只认 YAML；v2rayN / v2rayNG / 小火箭 认 base64 的 vless 列表。
        const ua = request.headers.get("user-agent") || "";
        const fmt = (url.searchParams.get("format") || "").toLowerCase();
        const wantClash = fmt === "clash" || fmt === "yaml"
          || url.searchParams.get("clash") === "1"
          || /clash|mihomo|stash|clashmeta|meta\//i.test(ua);

        if (wantClash) {
          const body = "proxies:\n" + vlessToClashProxies(finalNodeString) + "\n";
          return new Response(body, {
            headers: {
              "Content-Type": "text/yaml; charset=utf-8",
              "Profile-Update-Interval": "6",
              "Content-Disposition": "attachment; filename=\"config.yaml\"",
              ...NO_STORE
            }
          });
        }

        const base64Config = btoa(unescape(encodeURIComponent(finalNodeString)));

        return new Response(base64Config, {
          headers: {
            "Content-Type": "text/plain; charset=utf-8",
            "Profile-Update-Interval": "6",
            ...NO_STORE
          }
        });
      } catch (err) {
        return new Response("Decryption failed. Invalid key.", { status: 403, headers: NO_STORE });
      }
    }

    return new Response("Not Found", { status: 404, headers: NO_STORE });
  }
};
